 function chair(x,z,a=0){const p=new B.TransformNode('Pony chair',scene);p.parent=inn;p.position.set(x,0,z);p.rotation.y=a;box('Pony chair seat',timber,p,0,.55,0,.65,.12,.65);box('Pony chair back',timber,p,0,1.05,.28,.65,.85,.1);for(const dx of [-.23,.23])for(const dz of [-.23,.23])box('Pony chair leg',timber,p,dx,.25,dz,.08,.5,.08);}
