 for(const [parent,x,y,z,intensity,range]of [[town,0,4,-4,.8,22],[town,0,4,12,.7,18],[inn,0,3.5,-3,1,20],[inn,6.8,1.4,5,.9,14],[inn,0,3,13,.6,12]]){const l=new B.PointLight('Bree warm local light',new V(x,y,z),scene);l.parent=parent;l.diffuse=B.Color3.FromHexString('#ffd294');l.intensity=intensity;l.range=range;lights.push(l);}
 for(const [id,x,z,coat,parent,work]of [['bree-gatekeeper',2,-35,'#68705c',town,false],['bree-market-vendor',-10,-2,'#895949',town,true],['bree-lamplighter',5,-16,'#77745a',town,false],['bree-carrier',-5,8,'#6e6381',town,false],['barliman-butterbur',-5,4,'#827343',inn,true],['strider',5,5,'#394c3d',inn,false]]){const a=createTownResident(B,scene,{id,x,z,coat,scale:id==='strider'?1.17:1.05,hood:id==='strider',shadow:world.shadow});a.root.parent=parent;actors.push({...a,id,x,z,parent,work});}
